package com.cybershield.controller;
import com.cybershield.repository.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController { final IncidentRepository i; final UserRepository u; final ActivityLogRepository logs; public DashboardController(IncidentRepository i,UserRepository u,ActivityLogRepository l){this.i=i;this.u=u;this.logs=l;} @GetMapping @PreAuthorize("hasAnyRole('ADMIN','ANALYST')") public Map<String,Object> stats(){long total=i.count(),open=i.countByStatus("OPEN"),invest=i.countByStatus("INVESTIGATING"),resolved=i.countByStatus("RESOLVED"),critical=i.countBySeverity("CRITICAL"),high=i.countBySeverity("HIGH");return Map.of("total",total,"open",open,"investigating",invest,"resolved",resolved,"critical",critical,"high",high,"users",u.count(),"recentIncidents",i.findTop10ByOrderByCreatedAtDesc(),"recentActivity",logs.findTop50ByOrderByCreatedAtDesc());} }
